ALTER TABLE public.aircraft_types ADD COLUMN purchase_price numeric NOT NULL DEFAULT 0 CHECK(purchase_price>=0); UPDATE public.aircraft_types SET purchase_price=security_deposit*10;
ALTER TABLE public.fleet_aircraft ADD COLUMN ownership text NOT NULL DEFAULT 'LEASED' CHECK(ownership IN ('LEASED','OWNED')), ADD COLUMN purchase_price numeric NOT NULL DEFAULT 0 CHECK(purchase_price>=0);
CREATE UNIQUE INDEX fleet_registration_normalized ON public.fleet_aircraft(upper(trim(registration)));
CREATE TABLE public.registration_rules(country text PRIMARY KEY,prefix text NOT NULL,suffix_pattern text NOT NULL,suffix_length integer NOT NULL,alphabet text NOT NULL DEFAULT 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',source text NOT NULL DEFAULT 'https://www.avcodes.co.uk/regprefixcur.asp'); GRANT SELECT ON public.registration_rules TO authenticated; GRANT ALL ON public.registration_rules TO service_role; ALTER TABLE public.registration_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY "Players read registration rules" ON public.registration_rules FOR SELECT TO authenticated USING(true);
INSERT INTO public.registration_rules(country,prefix,suffix_pattern,suffix_length) SELECT DISTINCT a.country,v.prefix,CASE WHEN a.country='DE' THEN '[EGI][A-Z]{3}' WHEN a.country='FR' THEN '[GBH][A-Z]{3}' ELSE '[A-Z]{'||v.len||'}' END,v.len FROM airports a JOIN (VALUES ('PL','SP-',3),('DE','D-',4),('GB','G-',4),('FR','F-',4),('IT','I-',4),('ES','EC-',3),('AT','OE-',3),('CH','HB-',3),('CZ','OK-',3),('SK','OM-',3),('BE','OO-',3),('NL','PH-',3),('DK','OY-',3),('NO','LN-',3),('SE','SE-',3),('FI','OH-',3),('IE','EI-',3),('IS','TF-',3),('PT','CS-',3),('GR','SX-',3),('HU','HA-',3),('RO','YR-',3),('BG','LZ-',3),('EE','ES-',3),('LV','YL-',3),('LT','LY-',3),('LU','LX-',3),('MT','9H-',3),('CY','5B-',3),('HR','9A-',3),('SI','S5-',3),('RS','YU-',3),('ME','4O-',3),('BA','E7-',3),('MK','Z3-',3),('AL','ZA-',3),('TR','TC-',3),('UA','UR-',5),('SM','T7-',3),('IM','M-',4),('GG','2-',4),('JE','ZJ-',3)) v(country,prefix,len) ON a.country=v.country;
CREATE FUNCTION public.aircraft_registration(p_type text,p_requested text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r registration_rules%ROWTYPE; t aircraft_types%ROWTYPE; c text; candidate text; pattern text; head text:=''; i integer; j integer; BEGIN SELECT a.country INTO c FROM companies co JOIN airports a ON a.icao=co.home_base_icao WHERE co.user_id=auth.uid(); IF c IS NULL THEN RAISE EXCEPTION 'No company'; END IF; SELECT * INTO r FROM registration_rules WHERE country=c; IF NOT FOUND THEN RAISE EXCEPTION 'Registration rules unavailable for this base country'; END IF; SELECT * INTO t FROM aircraft_types WHERE id=p_type; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown aircraft'; END IF; pattern:=r.suffix_pattern; IF c='DE' THEN head:=CASE WHEN t.fuel_type='Jet-A' THEN 'I' WHEN t.tier=1 THEN 'E' ELSE 'G' END; pattern:=head||'[A-Z]{3}'; ELSIF c='FR' THEN head:='G'; END IF; IF p_requested IS NOT NULL AND trim(p_requested)<>'' THEN candidate:=upper(trim(p_requested)); IF candidate !~ ('^'||r.prefix||'('||pattern||')$') THEN RAISE EXCEPTION 'Registration must match % %',r.prefix,pattern; END IF; IF EXISTS(SELECT 1 FROM fleet_aircraft WHERE upper(trim(registration))=candidate) THEN RAISE EXCEPTION 'Registration already assigned'; END IF; RETURN candidate; END IF; FOR i IN 1..200 LOOP candidate:=r.prefix||head; FOR j IN 1..(r.suffix_length-length(head)) LOOP candidate:=candidate||substr(r.alphabet,1+floor(random()*length(r.alphabet))::int,1); END LOOP; IF NOT EXISTS(SELECT 1 FROM fleet_aircraft WHERE upper(trim(registration))=candidate) THEN RETURN candidate; END IF; END LOOP; RAISE EXCEPTION 'No registration available'; END $$;
REVOKE ALL ON FUNCTION public.aircraft_registration(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.aircraft_registration(text,text) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.sign_lease(text,integer)'::regprocedure) INTO d; d:=replace(d,'returned_at IS NULL)>=','returned_at IS NULL AND ownership=''LEASED'')>='); d:=replace(d,'reg:=''SS-''||c.icao_code||upper(substr(replace(fid::text,''-'',''''),1,6));','PERFORM pg_advisory_xact_lock(814503); reg:=public.aircraft_registration(p_type);'); EXECUTE d; END $$;
ALTER TABLE public.company_ledger DROP CONSTRAINT company_ledger_entry_type_check; ALTER TABLE public.company_ledger ADD CONSTRAINT company_ledger_entry_type_check CHECK(entry_type IN ('INITIAL_GRANT','LEASE_DEPOSIT','LEASE_PAYMENT','LEASE_DEPOSIT_REFUND','AIRCRAFT_PURCHASE','TICKET_REVENUE','FUEL_EXPENSE','AIRPORT_FEES','HANDLING_FEES','MAINTENANCE_RESERVE'));
CREATE FUNCTION public.purchase_aircraft(p_type text,p_registration text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; t aircraft_types%ROWTYPE; bal numeric; reg text; fid uuid:=gen_random_uuid(); BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM sync_lease_payments(); SELECT * INTO t FROM aircraft_types WHERE id=p_type AND active FOR SHARE; IF NOT FOUND OR t.purchase_price<=0 THEN RAISE EXCEPTION 'Aircraft unavailable for purchase'; END IF; bal:=company_balance(c.id); IF bal<t.purchase_price THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; PERFORM pg_advisory_xact_lock(814503); reg:=aircraft_registration(p_type,p_registration); INSERT INTO fleet_aircraft(id,company_id,aircraft_type_id,registration,location_icao,ownership,purchase_price,lease_deposit,weekly_rate,next_payment_due) VALUES(fid,c.id,t.id,reg,c.home_base_icao,'OWNED',t.purchase_price,0,0,now()); INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'AIRCRAFT_PURCHASE','AIRCRAFT_ASSET','COMPANY_CASH',t.purchase_price,-t.purchase_price,bal-t.purchase_price,'Aircraft purchase – '||reg,reg,'purchase:'||fid); RETURN fid; END $$; REVOKE ALL ON FUNCTION public.purchase_aircraft(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.purchase_aircraft(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_dispatch_lease() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM fleet_aircraft WHERE id=NEW.aircraft_id AND ownership='OWNED' AND returned_at IS NULL) THEN RETURN NEW; END IF; IF NOT EXISTS(SELECT 1 FROM lease_contracts k JOIN fleet_aircraft f ON f.id=k.aircraft_id WHERE k.aircraft_id=NEW.aircraft_id AND f.returned_at IS NULL AND now()>=k.starts_at AND now()<k.ends_at) THEN RAISE EXCEPTION 'Lease expired — renew before dispatch'; END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.flight_quote(uuid,text)'::regprocedure) INTO d; d:=replace(d,'IF NOT EXISTS(SELECT 1 FROM public.lease_contracts','IF f.ownership<>''OWNED'' AND NOT EXISTS(SELECT 1 FROM public.lease_contracts'); EXECUTE d; SELECT pg_get_functiondef('public.manage_lease(uuid,text,integer)'::regprocedure) INTO d; d:=replace(d,'IF f.returned_at IS NOT NULL THEN','IF f.ownership=''OWNED'' THEN RAISE EXCEPTION ''Owned aircraft has no lease''; END IF; IF f.returned_at IS NOT NULL THEN'); EXECUTE d; SELECT pg_get_functiondef('public.aircraft_finance(uuid)'::regprocedure) INTO d; d:=replace(d,'''revenue'',coalesce','''ownership'',f.ownership,''asset_value'',f.purchase_price,''revenue'',coalesce'); d:=replace(d,'round(k.weekly_rate/7,2)','coalesce(round(k.weekly_rate/7,2),0)'); EXECUTE d; END $$;